// Copy for every Team surface: directory, create, detail, settings, branding,
// members, Groups, invitations, and the public join screen.
//
// Team and Group names are presentation, never identity, so every interpolated
// string treats the name as a label. Consequence copy states what actually
// happens (retention, revocation, restricted Guest access) rather than implying
// a guarantee the Home does not make.

